'use strict';
// Home navigation performance test. No user data, persistent storage or accounting mutations.
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const html=fs.readFileSync('index.html','utf8');
const start=html.indexOf('let _ratibHomeRefreshSerial=0;');
const end=html.indexOf('function navigateToTab(',start);
assert(start>=0&&end>start,'Home after-paint scheduling helper must exist');
const helper=html.slice(start,end);
assert(html.includes("if(previousTab!=='pageDashboard'&&window.__ratibProceedInitialized===true)"),'Only home return after boot is deferred');
assert(html.includes("if(next!=='pageDashboard')_ratibHomeRefreshSerial++"),'Leaving home invalidates pending refresh');
assert(html.includes('    else{\n      _ratibHomeRefreshSerial++;\n      updateProDashboard();'),'First boot must still update KPIs synchronously');
assert(html.includes("if(next==='pageDashboard'&&!_restoringAppView)returnToAppHome();"),'Browser-history safety flow remains unchanged');
assert(html.includes("const depth=_appCurrentHistoryDepth;_appBackStack.length=0;_appSavedViews.clear();"),'History reset remains intact');
assert(!helper.includes('store.set(')&&!helper.includes('localStorage'),'Navigation helper must not mutate accounting data');
const rafs=[],timeouts=[],accounting={money:12968804.859999};
let refreshes=0;
const state={currentActiveTab:'pageDashboard',requestAnimationFrame:f=>{rafs.push(f);return rafs.length;},setTimeout:f=>{timeouts.push(f);return timeouts.length;},updateProDashboard:()=>{refreshes++;}};
vm.runInNewContext(helper+'\nthis.queueHomeRefresh=ratibRefreshDashboardAfterPaint;this.invalidate=()=>++_ratibHomeRefreshSerial;',state);
state.queueHomeRefresh();
assert.equal(refreshes,0,'First paint is not blocked by synchronous history/accounting refresh');
assert.equal(rafs.length,1);
rafs.shift()();assert.equal(refreshes,0,'Refresh stays deferred until after browser has had a paint opportunity');
assert.equal(timeouts.length,1);timeouts.shift()();assert.equal(refreshes,1);
state.queueHomeRefresh();rafs.shift()();state.invalidate();timeouts.shift()();
assert.equal(refreshes,1,'Stale callback is cancelled after leaving home');
state.queueHomeRefresh();rafs.shift()();state.currentActiveTab='pageLedger';timeouts.shift()();
assert.equal(refreshes,1,'Hidden home must not be refreshed');
state.currentActiveTab='pageDashboard';state.queueHomeRefresh();rafs.shift()();timeouts.shift()();
assert.equal(refreshes,2,'Home becomes fresh again on next valid return');
assert.equal(accounting.money,12968804.859999,'Original accounting value remains unchanged');
console.log('PASS: home paints first, background KPI refresh once, stale jobs cancelled, original history guards preserved');
